/**
 * ======================================================================
 * 【基本说明】：
 * MobileIMSDK-Web版服务端的Log4js配置项及日志工具提供类。
 *
 * 【基本用法】：
 * var logger = require('../j_conf/log').logger;
 * logger.info('Some log info......');
 * logger.deug('Some log info......');
 * logger.warn('Some log info......');
 * logger.error('Some log info......');
 *
 * 【参考资料】：
 * https://www.cnblogs.com/Joans/p/9647601.html
 * ======================================================================
 */

// log4js的输出级别6个: trace, debug, info, warn, error, fatal
var log4js = require('log4js');

log4js.configure({
    // 输出位置的基本信息设置
    appenders: {
        // 控制台输出
        console:{
            type: 'console',
        },
        // 日期文件日志记录，文件最大值maxLogSize 单位byte (B->KB->M) backups:备份的文件个数最大值,最新数据覆盖旧数据
        dateFileLog:{
            type: "file",
            filename: '../log.log', // 此日志输出目录可按需设置，方便查看日志文件
            pattern: "_yyyy-MM-dd",
            maxLogSize: 20480,
            backups: 3,
            category: 'dateFileLog'

        }
    },
    replaceConsole: true,   //替换console.log

    categories: {
        default: {
            appenders: ['console'],
            level: 'INFO', // 调整此值控制日志输出级别，官方级别：OFF、FATAL、ERROR、WARN、INFO、DEBUG、TRACE、ALL
        },
        dateFileLog: {
            appenders: ['console', 'dateFileLog'],
            level: 'INFO',
        },
    }
});


var dateFileLog = log4js.getLogger('dateFileLog');
var consoleLog = log4js.getLogger('console');
//exports.logger = dateFileLog; // 使用dateFileLog时日志将输出到文件（与consoleLog二选一）
exports.logger = consoleLog; // ##使用consoleLog时日志将仅输出到控制台（与dateFileLog二选一）
